def choose_move(observation):
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    s = observation.get("self_position") or (0, 0)
    o = observation.get("opponent_position")
    x, y = (s[0], s[1]) if isinstance(s, (list, tuple)) and len(s) >= 2 else (0, 0)

    def step(a, b):
        dx = 0 if b[0] == a[0] else (1 if b[0] > a[0] else -1)
        dy = 0 if b[1] == a[1] else (1 if b[1] > a[1] else -1)
        return [dx, dy]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    blocks = set()
    obs = observation.get("obstacles") or []
    for p in obs:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            blocks.add((p[0], p[1]))

    best = None
    best_d = 10**9
    res = observation.get("resources") or []
    for p in res:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            t = (p[0], p[1])
            d = dist((x, y), t)
            if d < best_d:
                best_d = d
                best = t

    cand = []
    if best is not None:
        cand.append(step((x, y), best))
    if o is not None and isinstance(o, (list, tuple)) and len(o) >= 2:
        cand.append(step((x, y), (2 * x - o[0], 2 * y - o[1])))
    if w and h:
        cand.append(step((x, y), (w // 2, h // 2)))
    cand.append([0, 0])

    for mv in cand:
        nx, ny = x + mv[0], y + mv[1]
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in blocks:
            return [mv[0], mv[1]]
    return [0, 0]

