def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def dist1(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "") or ""
    sx_sy = pos(observation.get("self_position"))
    ox_oy = pos(observation.get("opponent_position"))
    if sx_sy is None:
        sx_sy = (0, 0)
    sx, sy = sx_sy

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "") or "pursuer"
        if role == "pursuer":
            if ox_oy is not None:
                return step_toward((sx, sy), ox_oy)
            return [0, 0]
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        if ox_oy is not None:
            target = corners[0]
            best = -1
            for c in corners:
                d = dist1(c, ox_oy)
                if d > best:
                    best = d
                    target = c
            return step_toward((sx, sy), target)
        return [1, 1] if (sx + sy) % 2 == 0 else [-1, -1]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or []
        )
        best = None
        best_score = None
        for t in targets:
            tp = pos(t)
            if tp is None:
                continue
            score = dist1((sx, sy), tp)
            if best is None or score < best_score:
                best = tp
                best_score = score
        if best is not None:
            return step_toward((sx, sy), best)
        if ox_oy is not None:
            return step_toward((sx, sy), ox_oy)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = None
    best_score = None
    for r in resources:
        rp = pos(r)
        if rp is None:
            continue
        score = dist1((sx, sy), rp)
        if target is None or score < best_score:
            target = rp
            best_score = score

    if target is not None:
        return step_toward((sx, sy), target)

    if ox_oy is not None:
        if env == "resource_collection":
            if gw and gh:
                center = (gw // 2, gh // 2)
                away = (sx + clamp_step(sx - ox_oy[0]), sy + clamp_step(sy - ox_oy[1]))
                if dist1(away, ox_oy) >= dist1((sx, sy), ox_oy):
                    return [clamp_step(away[0] - sx), clamp_step(away[1] - sy)]
                return step_toward((sx, sy), center)
            return [clamp_step(sx - ox_oy[0]), clamp_step(sy - ox_oy[1])]
        return step_toward((sx, sy), ox_oy)

    if gw and gh:
        return [1 if sx * 2 < gw else -1 if sx * 2 > gw else 0, 1 if sy * 2 < gh else -1 if sy * 2 > gh else 0]

    return [0, 0]

